require_once dirname(__DIR__) . '/app/auth-capabilities.php';
require_once dirname(__DIR__) . '/app/data-slot.php';
require_once dirname(__DIR__) . '/app/leden/service.php';
require_once dirname(__DIR__) . '/operationele-taken-opslag.php';
if(!$ingelogd){header('Location: ./');exit;}
if(!authHeeftCapability('ops_tasks.manage')){http_response_code(403);echo'Geen toegang tot Operationele taken.';exit;}
function otEsc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function otFlash(string $t,string $type='ok'):void{$_SESSION['otaken_flash']=['tekst'=>$t,'type'=>$type];}
function otRedirect():void{header('Location: operationele-taken.php');exit;}
function otVind(array $data,string $id):?int{foreach($data['taken'] as $i=>$t)if(is_array($t)&&($t['id']??'')===$id)return$i;return null;}
$flash=$_SESSION['otaken_flash']??null;unset($_SESSION['otaken_flash']);
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!csrfOk()){otFlash('Sessie verlopen.','fout');otRedirect();}$slot=dataSlotOpen();try{$data=otakenLees();$actie=(string)($_POST['actie']??'');
  if($actie==='opslaan'){$id=trim((string)($_POST['id']??''));$idx=$id===''?null:otVind($data,$id);$bestaand=$idx===null?null:$data['taken'][$idx];$t=otaakNormaliseer(['omschrijving'=>$_POST['omschrijving']??'','toelichting'=>$_POST['toelichting']??'','frequentie'=>$_POST['frequentie']??'maandelijks','zichtbaarheid'=>$_POST['zichtbaarheid']??'leden','toegewezen_aan'=>$_POST['toegewezen_aan']??'','actief'=>!empty($_POST['actief'])],$bestaand);$geldige=array_column(ledenServiceLees()['leden'],'id');if($t['toegewezen_aan']!==''&&!in_array($t['toegewezen_aan'],$geldige,true))$t['toegewezen_aan']='';if($idx===null){$t['nummer']=otaakVolgendNummer($data);$t['aangemaakt_door']=$huidigeGebruiker;$data['taken'][]=$t;}else$data['taken'][$idx]=$t;if(otakenSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'operationele_taak_opgeslagen',$t['id']);otFlash('Operationele taak opgeslagen.');}else otFlash('Opslaan mislukt.','fout');}
  elseif($actie==='uitgevoerd'){$id=trim((string)($_POST['id']??''));$idx=otVind($data,$id);if($idx===null)otFlash('Taak niet gevonden.','fout');else{$data['taken'][$idx]=otaakMarkeerUitgevoerd($data['taken'][$idx],$huidigeGebruiker);if(otakenSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'operationele_taak_uitgevoerd',$id);otFlash('Uitvoering geregistreerd.');}else otFlash('Opslaan mislukt.','fout');}}
  elseif($actie==='verwijderen'){$id=trim((string)($_POST['id']??''));$idx=otVind($data,$id);if($idx===null)otFlash('Taak niet gevonden.','fout');else{array_splice($data['taken'],$idx,1);if(otakenSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'operationele_taak_verwijderd',$id);otFlash('Taak verwijderd.');}else otFlash('Verwijderen mislukt.','fout');}}
 }finally{dataSlotDicht($slot);}otRedirect();
}
$data=otakenLees();$lijst=otakenGesorteerd($data);$editId=trim((string)($_GET['edit']??''));$edit=null;if($editId!=='')foreach($data['taken'] as $t)if(is_array($t)&&($t['id']??'')===$editId){$edit=$t;break;}$toon=($_GET['nieuw']??'')==='1'||$edit!==null;$t=$edit??['frequentie'=>'maandelijks','zichtbaarheid'=>'leden','actief'=>true];$leden=array_values(array_filter(ledenServiceLees()['leden'],static fn($l)=>is_array($l)&&empty($l['gearchiveerd_op'])));
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Operationele taken</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{padding:14px 22px;background:#fff;border-bottom:1px solid #ddd8c0}.top a{color:#2d6260;font-weight:750;text-decoration:none}.wrap{max-width:1050px;margin:30px auto;padding:0 20px 70px}.card{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:20px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.veld label{display:block;font-weight:700;margin-bottom:5px}.veld input,.veld select,.veld textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d3ccb7;border-radius:8px;font:inherit}.veld textarea{min-height:110px}.btn{display:inline-block;border:1px solid #d3ccb7;background:#fff;color:#2d6260;border-radius:8px;padding:9px 12px;text-decoration:none;font:inherit;font-weight:750;cursor:pointer}.btn.primary{background:#3a7a77;color:#fff;border:0}.btn.danger{background:#fff0ed;color:#8b2e27}.actions{display:flex;gap:8px;flex-wrap:wrap}.item{border-top:1px solid #eee9db;padding:12px 0}.meta{font-size:13px;color:#68705f}.melding{padding:12px;border-radius:8px;background:#eaf6ee}.melding.fout{background:#fdeceb;color:#8b2e27}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><a href="./">← Beheer</a></div><main class="wrap"><h1>Operationele taken</h1><a class="btn primary" href="?nieuw=1">+ Taak</a><?php if($flash):?><div class="melding <?=otEsc($flash['type']??'')?>"><?=otEsc($flash['tekst']??'')?></div><?php endif;?><?php if($toon):?><section class="card"><h2><?=$edit?'Taak bewerken':'Nieuwe taak'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=otEsc($csrfToken)?>"><input type="hidden" name="actie" value="opslaan"><input type="hidden" name="id" value="<?=otEsc($edit['id']??'')?>"><div class="grid"><div class="veld"><label>Omschrijving</label><input name="omschrijving" maxlength="200" value="<?=otEsc($t['omschrijving']??'')?>"></div><div class="veld"><label>Frequentie</label><select name="frequentie"><?php foreach(otaakFrequenties() as $k=>$lab):?><option value="<?=otEsc($k)?>" <?=($t['frequentie']??'')===$k?'selected':''?>><?=otEsc($lab)?></option><?php endforeach;?></select></div><div class="veld"><label>Zichtbaarheid</label><select name="zichtbaarheid"><?php foreach(otaakZichtbaarheden() as $k=>$lab):?><option value="<?=otEsc($k)?>" <?=($t['zichtbaarheid']??'')===$k?'selected':''?>><?=otEsc($lab)?></option><?php endforeach;?></select></div><div class="veld"><label>Toegewezen aan</label><select name="toegewezen_aan"><option value="">Niemand</option><?php foreach($leden as $l):?><option value="<?=otEsc($l['id'])?>" <?=($t['toegewezen_aan']??'')===$l['id']?'selected':''?>><?=otEsc(ledenVolledigeNaam($l))?></option><?php endforeach;?></select></div></div><div class="veld"><label><input type="checkbox" name="actief" value="1" <?=!empty($t['actief'])?'checked':''?>> Actief</label></div><div class="veld"><label>Toelichting</label><textarea name="toelichting"><?=otEsc($t['toelichting']??'')?></textarea></div><div class="actions"><button class="btn primary" type="submit">Opslaan</button><a class="btn" href="operationele-taken.php">Annuleren</a></div></form></section><?php endif;?><section class="card"><h2>Overzicht</h2><?php foreach($lijst as $item):$status=otaakStatus($item);?><div class="item"><strong><?=otEsc(otaakWeergavenaam($item))?></strong><br><span class="meta"><?=otEsc(otaakStatusLabels()[$status]??$status)?> · <?=otEsc(otaakFrequenties()[$item['frequentie']??'']??'')?><?=!empty($item['volgende_uitvoering'])?' · volgende '.otEsc($item['volgende_uitvoering']):''?></span><div class="actions"><a class="btn" href="?edit=<?=otEsc($item['id'])?>">Bewerken</a><form method="post"><input type="hidden" name="csrf" value="<?=otEsc($csrfToken)?>"><input type="hidden" name="actie" value="uitgevoerd"><input type="hidden" name="id" value="<?=otEsc($item['id'])?>"><button class="btn primary" type="submit">Uitgevoerd</button></form><form method="post" onsubmit="return confirm('Taak verwijderen?');"><input type="hidden" name="csrf" value="<?=otEsc($csrfToken)?>"><input type="hidden" name="actie" value="verwijderen"><input type="hidden" name="id" value="<?=otEsc($item['id'])?>"><button class="btn danger" type="submit">Verwijderen</button></form></div></div><?php endforeach;?></section></main></body></html>
